$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

$ExpectedHead = "3ee6764"
$CommitMessage = "feat: add persistent worker heartbeat registry"

function Write-Utf8NoBom([string]$Path, [string]$Content) {
    $parent = Split-Path -Parent $Path
    if ($parent -and -not (Test-Path $parent)) {
        New-Item -ItemType Directory -Path $parent -Force | Out-Null
    }
    $encoding = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllText((Join-Path (Get-Location) $Path), $Content, $encoding)
}

$root = (Get-Location).Path
if (-not (Test-Path (Join-Path $root "pom.xml")) -or -not (Test-Path (Join-Path $root ".git"))) {
    throw "Run this script from the LYAPUNOV repository root."
}
$branch = (& git branch --show-current).Trim()
if ($branch -ne "main") { throw "Expected branch main, found '$branch'. Stop." }
$headNow = (& git rev-parse --short HEAD).Trim()
if ($headNow -ne $ExpectedHead) {
    throw "Expected Batch 05 base $ExpectedHead, found $headNow. Stop rather than applying against an unknown revision."
}
& git diff --quiet
if ($LASTEXITCODE -ne 0) { throw "Tracked working-tree changes detected. Commit or stash them before running this batch." }
& git diff --cached --quiet
if ($LASTEXITCODE -ne 0) { throw "Staged changes detected. Commit or unstage them before running this batch." }

$files = @(
    @{
        Path = 'src/main/java/com/lyapunov/repository/WorkerHeartbeat.java'
        Content = ''
    },
    @{
        Path = 'src/main/java/com/lyapunov/repository/WorkerHeartbeatRepository.java'
        Content = ''
    },
    @{
        Path = 'src/main/java/com/lyapunov/cli/WorkerHeartbeatCli.java'
        Content = ''
    },
    @{
        Path = 'src/test/java/com/lyapunov/repository/WorkerHeartbeatRepositoryTest.java'
        Content = ''
    },
    @{
        Path = 'docs/WORKER_HEARTBEATS.md'
        Content = ''
    },
    @{
        Path = 'docker/migrations/V006__worker_heartbeats.sql'
        Content = ''
    }
)

foreach ($file in $files) {
    $bytes = [Convert]::FromBase64String($file.Content)
    $content = [System.Text.Encoding]::UTF8.GetString($bytes)
    Write-Utf8NoBom $file.Path $content
    Write-Host "Wrote $($file.Path)"
}

$sqlPath = Join-Path $root "docker/init.sql"
$sql = [System.IO.File]::ReadAllText($sqlPath)
$marker = "-- Retry timestamps are cleared when an event is published or moved to DEAD."
if (-not $sql.Contains($marker)) { throw "Could not find expected schema insertion marker in docker/init.sql." }
if ($sql.Contains("CREATE TABLE IF NOT EXISTS worker_heartbeats")) {
    throw "worker_heartbeats schema already exists; refusing to duplicate it."
}
$ddl = @'
-- Durable process registry. One row represents the latest incarnation of a logical worker ID.
CREATE TABLE IF NOT EXISTS worker_heartbeats (
    worker_id VARCHAR(255) PRIMARY KEY,
    instance_id VARCHAR(255) NOT NULL,
    status VARCHAR(32) NOT NULL DEFAULT 'RUNNING',
    started_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT clock_timestamp(),
    last_seen_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT clock_timestamp(),
    last_successful_publish_at TIMESTAMP WITH TIME ZONE,
    published_count BIGINT NOT NULL DEFAULT 0 CHECK (published_count >= 0),
    failed_count BIGINT NOT NULL DEFAULT 0 CHECK (failed_count >= 0),
    stale_claim_count BIGINT NOT NULL DEFAULT 0 CHECK (stale_claim_count >= 0),
    last_error TEXT,
    CONSTRAINT chk_worker_heartbeat_status CHECK (status IN ('RUNNING', 'STOPPED'))
);

CREATE INDEX IF NOT EXISTS idx_worker_heartbeats_last_seen
    ON worker_heartbeats (last_seen_at DESC);

'@
$sql = $sql.Replace($marker, $ddl + $marker)
Write-Utf8NoBom "docker/init.sql" $sql
Write-Host "Updated docker/init.sql"

Write-Host "Running full Maven verification..."
& .\mvnw.cmd -B -ntp clean verify
if ($LASTEXITCODE -ne 0) {
    throw "Maven verification failed. No files were staged, committed, or pushed."
}

$paths = @(
    "docker/init.sql",
    "docker/migrations/V006__worker_heartbeats.sql",
    "src/main/java/com/lyapunov/repository/WorkerHeartbeat.java",
    "src/main/java/com/lyapunov/repository/WorkerHeartbeatRepository.java",
    "src/main/java/com/lyapunov/cli/WorkerHeartbeatCli.java",
    "src/test/java/com/lyapunov/repository/WorkerHeartbeatRepositoryTest.java",
    "docs/WORKER_HEARTBEATS.md"
)
& git add -- $paths
if ($LASTEXITCODE -ne 0) { throw "git add failed." }

& git diff --cached --check
if ($LASTEXITCODE -ne 0) { throw "Whitespace validation failed. Changes remain staged; nothing committed or pushed." }

& git commit -m $CommitMessage
if ($LASTEXITCODE -ne 0) { throw "Commit failed. Changes remain staged; nothing pushed." }

& git push origin main
if ($LASTEXITCODE -ne 0) { throw "Push failed. Commit exists locally; retry git push origin main after resolving the issue." }

Write-Host ""
Write-Host "BATCH 06 COMPLETE: verified, committed, and pushed."
& git log -1 --oneline
& git status -sb
